{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Golidocitinib, a pyrimidine-based kinase inhibitor with an indazole substituent, showed >80% oral bioavailability in healthy humans; its heteroaromatic pyrimidine/indazole framework and solubilizing groups are analogous to the query, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CC-292, an acrylamide-containing pyrimidine BTK inhibitor, demonstrated excellent oral bioavailability in humans; the shared acrylamide warhead and pyrimidine core make this a direct structural analogy supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Afatinib, an acrylamide-containing kinase inhibitor, showed good oral bioavailability in Phase I human studies; the acrylamide and aromatic heterocycle features support high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Zongertinib, an acrylamide-pyrimidine kinase inhibitor, was predicted to have 41% oral bioavailability in humans, which is well above the 20% threshold and supports a high-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tariquidar had low oral bioavailability in humans, but it lacks the acrylamide/pyrimidine kinase-inhibitor scaffold and is structurally distant from the query, so this contradictory evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acrylamide-containing pyrimidine kinase inhibitor with a solubilizing basic amine. Multiple structurally related acrylamide/pyrimidine kinase inhibitors show human oral bioavailability well above 20%, including >80%, excellent, good, and 41%. The only low-bioavailability analogue is structurally distant and lacks the key acrylamide/pyrimidine framework. Therefore, high oral bioavailability (F >= 20%) is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Morgan similarities to evidence molecules are modest (0.22-0.28), limiting quantitative transferability.",
    "Some supportive records are qualitative or predicted rather than absolute IV-comparison measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

